package com.example.lms.service;
import com.example.lms.dto.*; import com.example.lms.entity.*; import com.example.lms.exception.*; import com.example.lms.repository.*; import com.example.lms.util.StringUtils; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class StudentService { private final StudentProfileRepository students; private final AccountRepository accounts; private final PasswordEncoder passwords; public StudentService(StudentProfileRepository s,AccountRepository a,PasswordEncoder p){students=s;accounts=a;passwords=p;}
 @Transactional(readOnly=true) public org.springframework.data.domain.Page<StudentResponse> list(org.springframework.data.domain.Pageable pageable){return students.findAll(pageable).map(this::response);} @Transactional(readOnly=true) public StudentResponse get(Long id){return response(student(id));} @Transactional(readOnly=true) public StudentResponse getByUsername(String username){var profile = students.findByAccountUsername(username).orElseThrow(()->new ResourceNotFoundException("Student not found.")); return response(profile);}
 @Transactional public StudentResponse create(StudentRequest r){if(accounts.existsByUsername(r.username()))throw new ConflictException("Username is already in use.");var a=new Account();a.setUsername(r.username().trim());a.setPasswordHash(passwords.encode(r.password()));a.setRole(Role.STUDENT);var p=new StudentProfile();p.setAccount(accounts.save(a));apply(p,r);return response(students.save(p));}
 @Transactional public StudentResponse update(Long id,StudentUpdateRequest r){var p=student(id);if(!p.getAccount().getUsername().equals(r.username())&&accounts.existsByUsername(r.username()))throw new ConflictException("Username is already in use.");p.getAccount().setUsername(r.username().trim());apply(p,r);return response(students.save(p));}
 @Transactional public void delete(Long id){students.delete(student(id));} private StudentProfile student(Long id){return students.findById(id).orElseThrow(()->new ResourceNotFoundException("Student %d was not found.".formatted(id)));} private void apply(StudentProfile p,StudentRequest r){p.setName(r.name().trim());p.setEmail(StringUtils.blankToNull(r.email()));p.setPhone(StringUtils.blankToNull(r.phone()));} private void apply(StudentProfile p,StudentUpdateRequest r){apply(p, new StudentRequest(r.username(), null, r.name(), r.email(), r.phone()));} private StudentResponse response(StudentProfile p){var a=p.getAccount();return new StudentResponse(p.getId(),a.getId(),a.getUsername(),p.getName(),p.getEmail(),p.getPhone(),a.getRole().name());}}
